/* 女角列表 - 显示更多信息（当前女角直接复用 /当前女角/* 变量，避免镜像不同步） */
function renderHeroineList(){
  var heroines=mvuObj('女角');
  var curName=mvuObj('场景').当前女角名||'无';
  var curHeroine=mvuObj('当前女角');
  var keys=Object.keys(heroines).filter(function(k){return k&&k!=='0'&&k!=='无';});
  /* 如果当前女角名存在但 /女角/ 列表中没有对应条目，则把当前女角名加入列表（数据来自 /当前女角/*） */
  if(curName&&curName!=='无'&&keys.indexOf(curName)===-1){
    keys.push(curName);
  }
  var body='';
  if(keys.length===0){
    body='<div style="text-align:center;color:var(--c-dim);padding:10px;font-size:var(--fs-sm)">暂无女角数据<br><span style="font-size:var(--fs-xs)">等待女角登场</span></div>';
  }else{
    for(var i=0;i<keys.length;i++){
      var name=keys[i];
      /* 关键：当前女角直接复用 /当前女角/* 数据，其他女角读 /女角/${name}/* 镜像 */
      var h=(name===curName&&curHeroine&&curHeroine.姓名)?curHeroine:heroines[name];
      if(!h||typeof h!=='object')continue;
      var stage=h.关系阶段||'初识';
      var stageCls=stage==='初识'?'':(stage==='熟悉'?'safe':(stage==='暧昧'?'warn':(stage==='心动'||stage==='亲密'||stage==='攻略完成'?'pink':(stage==='失恋'?'warn':'danger'))));
      var curTag=(name===curName)?' <span class="cur-tag">★当前</span>':'';
      body+='<div class="heroine-item" data-act="heroine-detail" data-name="'+esc(name)+'">'
        +'<div class="heroine-row">'
        +'<span class="heroine-name">'+esc(name)+curTag+'</span>'
        +'<span class="heroine-stage '+stageCls+'">'+esc(stage)+'</span>'
        +'</div>'
        +'<div class="heroine-stats">'
        +'<span>好感:'+esc(h.好感度||0)+'</span>'
        +'<span>心动:'+esc(h.心动值||0)+'</span>'
        +'<span>信任:'+esc(h.信任度||0)+'</span>'
        +'<span>嫉妒:'+esc(h.嫉妒值||0)+'</span>'
        +'<span>H:'+esc(h.H经验次数||0)+'</span>'
        +'<span>初吻:'+(h.初吻?'✓':'✗')+'</span>'
        +'<span>初H:'+(h.初H?'✓':'✗')+'</span>'
        +'</div></div>';
    }
  }
  return cardTitle('list','👥','女角列表 ('+keys.length+'/20)','heroineList')+body+'</div></details>';
}

