/* 基础属性分档（5 档，与 SKILL_RULES.threshold_stages 对齐） */
function getStatTier(value) {
  const v = Number(value) || 0;
  if (v >= 90) return '大师';
  if (v >= 70) return '精通';
  if (v >= 50) return '熟练';
  if (v >= 30) return '入门';
  return '生疏';
}

/* 性格特质分档（5 档，与 PERSONALITY_TRAITS.thresholds 对齐） */
function getPersonalityTier(value) {
  const v = Number(value) || 0;
  if (v >= 80) return '极尽';
  if (v >= 60) return '高';
  if (v >= 40) return '平衡';
  if (v >= 20) return '低';
  return '极低';
}

/* 技能分档（5 档，与 SKILL_RULES.threshold_stages 对齐） */
function getSkillTier(value) {
  const v = Number(value) || 0;
  if (v >= 90) return '大师';
  if (v >= 70) return '精通';
  if (v >= 50) return '熟练';
  if (v >= 30) return '入门';
  return '生疏';
}

/* 将三层属性转为分档摘要（不输出数值，控制 token） */
function buildStatTiers(stats) {
  const _r = {};
  for (const _k in stats) _r[_k] = getStatTier(stats[_k]);
  return _r;
}
function buildPersonalityTiers(personality) {
  const _r = {};
  for (const _k in personality) _r[_k] = getPersonalityTier(personality[_k]);
  return _r;
}
function buildSkillTiers(skills) {
  /* 仅输出关键技能，控制 token（其余技能在判定时按需读取） */
  return {
    romance:     getSkillTier(skills.romance),
    observation: getSkillTier(skills.observation),
    speech:      getSkillTier(skills.speech),
    stealth:     getSkillTier(skills.stealth),
    strength:    getSkillTier(skills.strength),
    intelligence:getSkillTier(skills.intelligence)
  };
