/* 检测主角性格原型（基于三层属性组合匹配，至少 60% 维度匹配才算该原型） */
function detectPlayerArchetype(stats, personality, skills) {
  let _bestMatch = null;
  let _bestScore = 0;
  for (const _name in PLAYER_ARCHETYPES) {
    const _arch = PLAYER_ARCHETYPES[_name];
    let _matched = 0;
    let _total = 0;
    for (const _key in _arch.match) {
      const _range = _arch.match[_key];
      let _val = 0;
      if (Object.prototype.hasOwnProperty.call(stats, _key)) _val = Number(stats[_key]) || 0;
      else if (Object.prototype.hasOwnProperty.call(personality, _key)) _val = Number(personality[_key]) || 0;
      else if (Object.prototype.hasOwnProperty.call(skills, _key)) _val = Number(skills[_key]) || 0;
      _total++;
      if (_val >= _range[0] && _val <= _range[1]) _matched++;
    }
    const _score = _total > 0 ? _matched / _total : 0;
    if (_score > _bestScore && _score >= 0.6) {
      _bestScore = _score;
      _bestMatch = {
        archetype: _name,
        match_ratio: Math.round(_score * 100) / 100,
        narrative_style: _arch.narrative_style,
        strengths: _arch.strengths,
        weaknesses: _arch.weaknesses
      };
    }
  }
  return _bestMatch || {
    archetype: '平衡型',
    match_ratio: 0,
    narrative_style: 'AI标准描写，视情境综合三层属性发挥',
    strengths: [],
    weaknesses: []
  };
}

