var _HOSPITAL_THRESHOLD = (_difficulty === '轻松') ? 3 : (_difficulty === '普通') ? 5 : (_difficulty === '挑战') ? 7 : 10;
var _hospitalVisits = Number(getvar('stat_data.隐藏.医院访问次数', { scope: 'local', defaults: 0 })) || 0;
var _sakurakoRouteUnlocked = Boolean(getvar('stat_data.隐藏.樱子线解锁', { scope: 'local', defaults: false }));
var _isAtHospital = (_currentLocation && String(_currentLocation).indexOf('市民医院') >= 0);
%>
<% if (_isAtHospital && !_sakurakoRouteUnlocked) { %>
