<%
/* 9.B.11: 日记本收集追踪 */
var _diaryFlags = [
  { id: 1, flag: '日记1', day_range: [1, 1],  time_slot: '早',   location_match: '自宅',   action: '检查书桌抽屉', name: '第1本·开局日记' },
  { id: 2, flag: '日记2', day_range: [2, 7],  time_slot: 'any',   location_match: '占卜',   action: '帮川尻信良还书给梦仙人', name: '第2本·梦仙人还书' },
  { id: 3, flag: '日记3', day_range: [15, 17], time_slot: '晚',   location_match: '鸣泽家', action: '唯主动交付（需 唯获救=true + 唯.affection≥50）', name: '第3本·唯交付' },
  { id: 4, flag: '日记4', day_range: [9, 14],  time_slot: '下午', location_match: '保育园', action: '爱美谢礼（需 爱美获救=true）', name: '第4本·爱美谢礼' },
  { id: 5, flag: '日记5', day_range: [14, 16], time_slot: '下午', location_match: '电视台', action: '可怜带主角去录影（需 karen_unmasked=true）', name: '第5本·电视台录影' }
];
var _diaryCollectibleNow = [];
_diaryFlags.forEach(function(_d) {
  var _collected = Number(getvar(`stat_data.隐藏.${_d.flag}`, { scope: 'local', defaults: 0 })) === 1;
  if (_collected) return;
  var _inDayRange = (_dayCount >= _d.day_range[0] && _dayCount <= _d.day_range[1]);
