  if (_inDayRange && _inTimeSlot && _inLocation) {
    _diaryCollectibleNow.push(_d);
  }
});
var _diaryProgress = {
  collected: _diaryFlags.filter(function(_d) { return Number(getvar(`stat_data.隐藏.${_d.flag}`, { scope: 'local', defaults: 0 })) === 1; }).length,
  total: 5,
  collected_list: _diaryFlags.filter(function(_d) { return Number(getvar(`stat_data.隐藏.${_d.flag}`, { scope: 'local', defaults: 0 })) === 1; }).map(function(_d) { return _d.id; }),
  missing_list: _diaryFlags.filter(function(_d) { return Number(getvar(`stat_data.隐藏.${_d.flag}`, { scope: 'local', defaults: 0 })) !== 1; }).map(function(_d) { return _d.id; })
};
%>
<% if (_diaryCollectibleNow.length > 0) { %>
[系统提示 · 日记本可收集（9.B.11）]
