<% _diaryCollectibleNow.forEach(function(_d) { %>
────────────────────────────
日记：<%= _d.name %>
触发条件：day <%= _d.day_range[0] %>-<%= _d.day_range[1] %> / 时段 <%= _d.time_slot %> / 场景含「<%= _d.location_match %>」
