/* ════════════════════════════════════════════════════════════
   三、辅助函数（供 属性技能骰子联动.txt 与其他控制器调用）
   ════════════════════════════════════════════════════════════ */

/* getHeroinePreferenceRaw(heroine_id, action_type)
   读取女角原始偏好（不应用难度修正）。
   与 属性技能骰子联动.txt 的 getHeroinePreference() 兼容，作为兜底入口。
   返回 { stat_weights, personality_weights, skill_weights }。 */
function getHeroinePreferenceRaw(heroine_id, action_type) {
  var _id = Number(heroine_id) || 0;
  var _action = action_type || 'default';
  if (typeof HEROINE_PREFERENCES === 'undefined') {
    return {
      stat_weights: { charm: 1, academic: 1, physical: 1, social: 1, perception: 1, willpower: 1 },
      personality_weights: { gentleness: 1, decisiveness: 1, humor: 1, cautiousness: 1, extraversion: 1, rationality: 1 },
      skill_weights: { strength: 1, agility: 1, intelligence: 1, willpower: 1, stealth: 1, speech: 1, medical: 1, cooking: 1, art: 1, driving: 1, romance: 1, observation: 1 }
    };
  }
  var _prefs = HEROINE_PREFERENCES[_id];
  if (!_prefs) {
    return {
      stat_weights: { charm: 1, academic: 1, physical: 1, social: 1, perception: 1, willpower: 1 },
      personality_weights: { gentleness: 1, decisiveness: 1, humor: 1, cautiousness: 1, extraversion: 1, rationality: 1 },
      skill_weights: { strength: 1, agility: 1, intelligence: 1, willpower: 1, stealth: 1, speech: 1, medical: 1, cooking: 1, art: 1, driving: 1, romance: 1, observation: 1 }
    };
  }
  /* 优先按动作类型读取，回退到 default */
  var _entry = _prefs[_action] || _prefs.default || _prefs;
  /* 合并 default 与动作覆盖（动作覆盖仅替换已定义字段，其余继承 default） */
  var _defaultEntry = _prefs.default || {};
  return {
    stat_weights: Object.assign({}, _defaultEntry.stat_weights || {}, _entry.stat_weights || {}),
    personality_weights: Object.assign({}, _defaultEntry.personality_weights || {}, _entry.personality_weights || {}),
    skill_weights: Object.assign({}, _defaultEntry.skill_weights || {}, _entry.skill_weights || {})
  };
}

/* getHeroinePreferenceByDifficulty(heroine_id, action_type, difficulty)
   读取女角偏好并应用难度修正（weight_mult 缩放所有权重）。
   难度越高 → 权重越小 → 高权重优势削弱 → 能力值计算更难达标。
   同时返回 difficulty_bonus（女角个人难度的难度档位加成，需叠加到 HEROINE_DIFFICULTY）。
   返回 { stat_weights, personality_weights, skill_weights, difficulty_bonus }。 */
function getHeroinePreferenceByDifficulty(heroine_id, action_type, difficulty) {
  var _raw = getHeroinePreferenceRaw(heroine_id, action_type);
  var _diff = difficulty;
  var _mod = (DIFFICULTY_WEIGHT_MODIFIERS[_diff] || DIFFICULTY_WEIGHT_MODIFIERS['普通']);
  var _mult = Number(_mod.weight_mult) || 1.0;
  var _bonus = Number(_mod.difficulty_bonus) || 0;

  /* 对所有权重应用 weight_mult（保留 2 位小数） */
  var _scaleWeight = function(weights) {
    var _result = {};
    for (var _k in weights) {
      _result[_k] = Math.round((Number(weights[_k]) || 0) * _mult * 100) / 100;
    }
    return _result;
  };

  return {
    stat_weights: _scaleWeight(_raw.stat_weights),
    personality_weights: _scaleWeight(_raw.personality_weights),
    skill_weights: _scaleWeight(_raw.skill_weights),
    difficulty_bonus: _bonus,
    weight_mult: _mult,
    difficulty: _diff
  };
}

/* getHeroineEffectiveDifficulty(heroine_id, difficulty)
   计算女角有效难度系数 = 基础个人难度 + 难度档位加成。
   返回数值（加到要求值上）。
   注：与 属性技能骰子联动.txt HEROINE_DIFFICULTY 叠加使用，
       最终要求值修正 = HEROINE_DIFFICULTY[id] + difficulty_bonus + DIFFICULTY_MODIFIERS.req_mod */
function getHeroineEffectiveDifficulty(heroine_id, difficulty) {
  var _id = Number(heroine_id) || 0;
  var _prefs = (typeof HEROINE_PREFERENCES !== 'undefined') ? HEROINE_PREFERENCES[_id] : null;
  var _baseDiff = _prefs ? (Number(_prefs.difficulty_coefficient) || 0) : 0;
  var _mod = (DIFFICULTY_WEIGHT_MODIFIERS[difficulty] || DIFFICULTY_WEIGHT_MODIFIERS['普通']);
  var _bonus = Number(_mod.difficulty_bonus) || 0;
  return _baseDiff + _bonus;
}

/* verifyWeightBalance()
   校验所有女角权重总和是否符合平衡约束（开发期调试用）。
   返回 { passed, violations, summary }。 */
function verifyWeightBalance() {
  var _violations = [];
  var _summary = [];
  for (var _id in HEROINE_PREFERENCES) {
    var _h = HEROINE_PREFERENCES[_id];
    var _statSum = 0, _persSum = 0, _sklSum = 0;
    for (var _k in _h.default.stat_weights) _statSum += Number(_h.default.stat_weights[_k]) || 0;
    for (var _k in _h.default.personality_weights) _persSum += Number(_h.default.personality_weights[_k]) || 0;
    for (var _k in _h.default.skill_weights) _sklSum += Number(_h.default.skill_weights[_k]) || 0;
    var _maxWeight = 0;
    var _checkMax = function(w) { for (var _k in w) { var _v = Number(w[_k]) || 0; if (_v > _maxWeight) _maxWeight = _v; } };
    _checkMax(_h.default.stat_weights);
    _checkMax(_h.default.personality_weights);
    _checkMax(_h.default.skill_weights);
    var _entry = { id: Number(_id), name: _h.name, stat_sum: Math.round(_statSum * 100) / 100, pers_sum: Math.round(_persSum * 100) / 100, skl_sum: Math.round(_sklSum * 100) / 100, max_weight: _maxWeight };
    _summary.push(_entry);
    if (_statSum < 5.0 || _statSum > 7.0) _violations.push({ id: Number(_id), name: _h.name, field: 'stat_weights', sum: _statSum, range: '5.0-7.0' });
    if (_persSum < 5.0 || _persSum > 7.0) _violations.push({ id: Number(_id), name: _h.name, field: 'personality_weights', sum: _persSum, range: '5.0-7.0' });
    if (_sklSum < 8.0 || _sklSum > 12.0) _violations.push({ id: Number(_id), name: _h.name, field: 'skill_weights', sum: _sklSum, range: '8.0-12.0' });
    if (_maxWeight > 2.0) _violations.push({ id: Number(_id), name: _h.name, field: 'max_weight', value: _maxWeight, limit: 2.0 });
  }
  return { passed: _violations.length === 0, violations: _violations, summary: _summary };
}
