  }
  /* 8. BAD_END_8 时间终焉：第 17 天结束（必然触发兜底）*/
  if (_dayCount >= 17 && _date === '01-07') {
    /* 仅当上述 BAD_END 均未触发且所有女角 affection < 30 时进入 */
